import { createClient } from 'npm:@supabase/supabase-js@2.50.0';
import { agendaWindow, CLIENT_ID, renderEmail } from './email.ts';

Deno.serve(async (req: Request) => {
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405 });
  if (req.headers.get('authorization') !== `Bearer ${key}`) return new Response('Unauthorized', { status: 401 });
  const db = createClient(Deno.env.get('SUPABASE_URL')!, key);
  try {
    const { data: jobs, error } = await db.rpc('claim_ourense_portal_emails');
    if (error) throw error;
    let sent = 0;
    for (const job of jobs || []) {
      try {
        let payload = job.payload;
        if (!payload) {
          const window = agendaWindow();
          const { data: tasks, error: taskError } = await db.from('tasks').select('id,date,start_time,property,status').eq('cliente_id', CLIENT_ID).gte('date', window.start).lt('date', window.end).not('status', 'in', '(completed,cancelled,canceled)').order('date').order('start_time').order('id');
          if (taskError) throw taskError;
          // A cancellation can leave a task behind if the portal's separate delete failed.
          const { data: cancelled, error: cancelError } = await db.from('client_reservations').select('task_id').eq('client_id', CLIENT_ID).eq('status', 'cancelled').not('task_id', 'is', null);
          if (cancelError) throw cancelError;
          const removed = new Set((cancelled || []).map(r => r.task_id));
          payload = renderEmail(job.event, (tasks || []).filter(t => !removed.has(t.id)), window);
          const { error: saveError } = await db.from('ourense_portal_email_queue').update({ payload }).eq('id', job.id);
          if (saveError) throw saveError;
        }
        const response = await fetch('https://api.resend.com/emails', {
          method: 'POST', headers: { Authorization: `Bearer ${Deno.env.get('RESEND_API_KEY')}`, 'Content-Type': 'application/json', 'Idempotency-Key': `ourense-portal/${job.id}` }, body: JSON.stringify(payload), signal: AbortSignal.timeout(15000),
        });
        if (!response.ok) throw new Error(`Resend HTTP ${response.status}`);
        const result = await response.json();
        if (!result.id) throw new Error('Resend did not return an email id');
        const { error: finishError } = await db.from('ourense_portal_email_queue').update({ sent_at: new Date().toISOString(), provider_id: result.id, last_error: null }).eq('id', job.id);
        if (finishError) throw finishError;
        sent++;
      } catch (error) {
        console.error('Ourense email failed', job.id, String(error));
        await db.from('ourense_portal_email_queue').update({ last_error: String(error).slice(0, 500) }).eq('id', job.id);
      }
    }
    return Response.json({ processed: jobs?.length || 0, sent });
  } catch (error) {
    console.error('Ourense email worker failed', String(error));
    return Response.json({ error: 'Email worker failed' }, { status: 500 });
  }
});

export const CLIENT_ID = '983917ea-3e58-40ff-8437-06a8b2456a43';
export const RECIPIENT = 'ilopez@limpatex.com';
const escape = (value: unknown) => String(value ?? '—').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export function dateLabel(value: unknown): string {
  if (!value) return '—';
  const date = new Date(`${String(value).slice(0, 10)}T12:00:00Z`);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString('es-ES', { timeZone: 'Europe/Madrid', weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
}
export function agendaWindow(now = new Date()) {
  const start = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
  const end = new Date(`${start}T12:00:00Z`);
  end.setUTCDate(end.getUTCDate() + 14);
  return { start, end: end.toISOString().slice(0, 10) };
}
type Data = Record<string, unknown>;
export function renderEmail(log: { action: string; property_name: string; old_data?: Data; new_data?: Data; created_at: string }, tasks: Data[], window: { start: string; end: string }) {
  const action = { created: 'Tarea añadida', updated: 'Tarea modificada', cancelled: 'Tarea cancelada / eliminada' }[log.action] || 'Cambio en tarea';
  const old = log.old_data || {};
  const next = log.new_data || {};
  const fields = [['propertyName', 'Alojamiento'], ['checkInDate', 'Entrada de huéspedes'], ['checkOutDate', 'Día de limpieza (salida)'], ['guestCount', 'Huéspedes'], ['specialRequests', 'Notas']] as const;
  const value = (data: Data, key: string) => escape(key.endsWith('Date') ? dateLabel(data[key]) : data[key]);
  const rows = fields.filter(([key]) => log.action !== 'updated' || (old[key] ?? '') !== (next[key] ?? '')).map(([key, label]) => `<tr><td>${label}</td>${log.action === 'updated' ? `<td>${value(old, key)}</td>` : ''}<td><strong>${value(log.action === 'cancelled' ? old : next, key)}</strong></td></tr>`).join('');
  const status = (s: unknown) => ({ pending: 'Pendiente', assigned: 'Asignada', 'in-progress': 'En curso', in_progress: 'En curso' }[String(s)] || String(s ?? 'Pendiente'));
  const agenda = tasks.length ? `<table><tr><th>Día</th><th>Hora</th><th>Alojamiento</th><th>Estado</th></tr>${tasks.map(t => `<tr><td>${escape(dateLabel(t.date))}</td><td>${escape(String(t.start_time || 'Por concretar').slice(0, t.start_time ? 5 : undefined))}</td><td>${escape(t.property)}</td><td>${escape(status(t.status))}</td></tr>`).join('')}</table>` : '<p>No hay tareas pendientes en este periodo.</p>';

  return {
    from: 'Sistema de Gestión <alertas@limpatexgestion.es>', to: [RECIPIENT],
    subject: `Ourense · ${action} · ${log.property_name || 'Moba Skill Training SL'}`,
    html: `<!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width, initial-scale=1"><style>body{font-family:Arial,sans-serif;color:#172534;background:#f3f5f7;margin:0;padding:16px}main{max-width:680px;margin:auto;background:white;padding:24px;border-radius:12px}h1{font-size:24px}h2{font-size:19px;margin-top:30px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:10px 6px;border-bottom:1px solid #dde3e8;vertical-align:top;overflow-wrap:anywhere}th{background:#edf3f7}p{line-height:1.5}.muted{color:#526272;font-size:13px}</style></head><body><main><p class="muted">LIMPATEX · OURENSE · PORTAL DEL CLIENTE</p><h1>${action}</h1><p><strong>Moba Skill Training SL</strong><br>${escape(log.property_name)}</p><p class="muted">Cambio registrado el ${escape(new Date(log.created_at).toLocaleString('es-ES', { timeZone: 'Europe/Madrid' }))}</p><table><tr><th>Detalle</th>${log.action === 'updated' ? '<th>Antes</th><th>Ahora</th>' : '<th>Datos de la tarea</th>'}</tr>${rows || '<tr><td colspan="3">Sin cambios en los datos de la reserva.</td></tr>'}</table>${log.action === 'cancelled' ? '<p>El cliente ha cancelado esta reserva. La limpieza ya no forma parte de su agenda de reservas activas.</p>' : ''}<h2>Próximos 14 días · ${tasks.length} tarea${tasks.length === 1 ? '' : 's'}</h2>${agenda}</main></body></html>`,
  };
}
